export type Category = 'REPORTS' | 'ANALYSIS' | 'TIMELINE' | 'OPINION'

export type SourceFile = {
  label: string
  url: string
}

/** Optional YouTube (or clean embed URL) exhibit on an article. */
export type ArticleEmbed = {
  type: 'youtube'
  /** Raw 11-character YouTube video id */
  id?: string
  /** watch?v= / youtu.be / shorts / embed URL — normalized to nocookie */
  youtubeUrl?: string
  /** https youtube.com/embed/... or youtube-nocookie.com/embed/... */
  embedUrl?: string
  title?: string
  caption?: string
  /**
   * Insert after this 0-based body paragraph index.
   * Omit → after last body graf (before SOURCE FILES).
   */
  afterBodyIndex?: number
}

export type Article = {
  slug: string
  title: string
  category: Category
  date: string
  dek: string
  body: string[]
  sources: SourceFile[]
  published: boolean
  /** Optional video embeds (YouTube → youtube-nocookie). Reed/Ink fill these. */
  embeds?: ArticleEmbed[]
  /**
   * Engineering fixture — published for direct /reports/:slug access + static
   * HTML, but excluded from home / reports feeds.
   */
  fixture?: boolean
  /**
   * Continuous snark prose — no FACT/ANALYSIS/SATIRE body labels;
   * DossierCover omits tone Stamp chips when true.
   */
  proseArticle?: boolean
  /** Share card (og:image) kicker tape — short topic beat taken from the hed. */
  ogKicker?: string
  /** Word/phrase already in the hed to get the red highlight band. */
  ogPunch?: string
  /** Mood stamp: FILED / RECEIPTS / ON TAPE / IN WRITING. Never FACT/REPORT/ANALYSIS/SATIRE. */
  ogStamp?: string
  /** Override dossier number, e.g. 'FILE // 007'. Default derives from order. */
  ogFile?: string
  /** <title> override (SEO). The on-page headline stays `title`. */
  seoTitle?: string
  /** meta/OG/Twitter description override (SEO). Default `dek`. */
  seoDescription?: string
  /** 'clip' = short video post at /trump-videos/<slug>/ (v4 ClipPost). Default 'article' at /reports/<slug>/. */
  kind?: 'article' | 'clip'
  /** ClipPost: the original upload, embedded (never re-hosted). hed = title, kicker = ogKicker. */
  embed?: ClipEmbed
  /** ClipPost: optional "before" clip shown under the main embed. */
  beforeEmbed?: ClipEmbed & { label?: string }
  /** ClipPost: display duration, e.g. "1:42". */
  duration?: string
  /** YouTube-first: when set, the clip's main player is this YouTube upload (plays inline); the X post becomes an 'Also on X' credit. Set with scripts/set-youtube.mjs. */
  youtubeId?: string
  /** Pulled from the site while kept for later: no page (301 to /trump-videos/), no hubs, feeds, sitemaps, digest or X queue. */
  unlisted?: boolean
  /** Correction line shown at the bottom of SOURCE FILES. */
  correction?: string
  /** Seconds into the YouTube video where the clip starts. */
  youtubeStart?: number
  /** Uploader's channel name for the credit, e.g. 'The White House'. */
  youtubeChannel?: string
  /** Frame carries a chyron/banner (e.g. White House "Text POTUS" lower third): use the share card as the poster, like Fox. */
  posterShareCard?: boolean
  /** ClipPost: duration in seconds (for ISO 8601 PT…S). */
  durationSeconds?: number
  /** ClipPost: when we published, ISO with offset. */
  publishedAt?: string
  updatedAt?: string
  topics?: Topic[]
  /** Midterms 2026 hub filter chips (only read when topics includes 'midterms'). */
  midtermsTags?: MidtermsTag[]
  featured?: boolean
  /** Slug of the long-form file this clip belongs to. */
  relatedArticle?: string
  /** Slugs of related clips (also used on articles to link back to their clips). */
  relatedClips?: string[]
}

export type Topic = 'gaffes' | 'lies' | 'ballroom' | 'tariffs' | 'truth-social' | 'courts' | 'cruelty' | 'midterms'

/** /midterms-2026/ chips: Results, His claims vs the record, Endorsees, Truth Social. */
export type MidtermsTag = 'results' | 'claims' | 'endorsees' | 'truth-social'

export type ClipEmbed = {
  type: 'x' | 'youtube' | 'truthsocial'
  id: string
  url: string
  account?: string
  accountName?: string
  poster?: string
  /** truthsocial only: trumpstruth.org archive link for the quote card. */
  archiveUrl?: string
  /** truthsocial only: 'image' when the post is an image (card note says so); default is a text post. */
  truthType?: 'text' | 'image'
}

/** Site path for any post: clips live under /trump-videos/, files under /reports/. */
export function hrefFor(a: Pick<Article, 'slug' | 'kind'>): string {
  return a.kind === 'clip' ? `/trump-videos/${a.slug}/` : `/reports/${a.slug}`
}

