      'Most polls were still hours from opening. The president’s thumbs were not. At 12:52am ET on Tuesday, Trump went after Michigan’s Democratic Senate candidate one more time, and this time he tried to cover every group at once.',
      '“Abdul El-Sayed Hates Jews and Hates Blacks,” he wrote. “Don’t feel bad, he also Hates Whites.” Trump offered no evidence for any of it. El-Sayed, an outspoken critic of Israel’s military campaign in Gaza, has faced accusations of antisemitism over those positions, and his campaign has rejected criticism of his views on Israel, Mediaite reports. Trump also promised El-Sayed “will, 100%, do you in!”',
