      'Donald Trump closed out his election-eve speech with a victory lap for a war he isn’t sure was a war.',
      '“We had a war with Iran,” he said at the Lincoln Memorial, and “we won.” A few seconds later: “I don’t know if you even call it a war because we haven’t been doing any fighting for months.” He came back to it a minute on. If you think “we’re talking about war, it’s not a war,” he said, and there’s been “very little fighting.” Iran’s leaders, he said, have asked the US to stop wiping them out, “and we will.”',
