      'Asked why he’d hold an event there, he said: “Just to show how beautiful it is. It’s been finished. It was vandalized badly.” Also, he said it hasn’t worked since 1922, and “It’s always leaked terribly.” And then the new bit: “they vandalized the hell out of it, including the grass,” with a “certain thing that I won’t even say.” The finale: “They burned it out with acid.” He offered no evidence for any of it.',
