      'Donald Trump’s advice to a president sending troops into Haiti fits in nine words, and he said them twice.',
      'At his Mar-a-Lago Halloween party gaggle on Saturday, a reporter asked if he’d spoken to Nayib Bukele, El Salvador’s president, about Haiti. “I did,” Trump said. Bukele, he said, “has a big problem with Haiti,” and Trump told him: “Look, you’re running your country. You have to do what you have to do.” Then he said it again, adding, “They killed some of his people.” Asked whether the U.S. would help, Trump said Bukele didn’t need it: “He’s in pretty good shape.”',
