      'Donald Trump has a new Hollywood policy: insult the talent, then take the meeting.',
      'At Friday’s Daytona Beach rally, after complaining that at the Oscars “people get up and use foul language about your favorite president,” Trump asked the crowd, “By the way, is Robert De Niro a moron?” He took the question himself: “He’s a moron.” Then the review: “I used to sort of like him,” but “now I can’t even watch him.” Also: “He’s no good for comedies.”',
      'Then the turn. After lumping De Niro in with “a couple of the other losers out there,” Trump said Hollywood is “all calling me, kissing my ass. They want tax credits for Hollywood because Hollywood’s dying.” That’s his account. Which stars? He didn’t say. His impression of them: “Sir, could we please meet you?” His answer: “Now they want tax credits because their industry is dying in this country. And I’ll probably do it.” He asked the crowd whether he should. The Factba.se transcript records the audience answering “No.” Then he complained that he’s being lobbied.',
      'His last plan to save Hollywood was a 100% tariff on movies made outside the United States, announced on Truth Social in May 2025. Reuters reported it came with no details, and Business Insider reported in March that it still hadn’t been implemented. Netflix’s Ted Sarandos says he asked Trump to skip the tariffs and offer incentives instead. De Niro, 83, called Trump a “coward” at an Indivisible event on 4 Oct, per USA Today.',
