      'Donald Trump has given the Iran war an end date: whenever Donald Trump feels like it. Telling his Lubbock rally on Tuesday about a question he’d been asked earlier, “when will the war in Iran end?”, he said his answer was that it ends when he wants it to. He’d already said as much a few seconds before, in nearly the same words. Hours later, after midnight at Joint Base Andrews, asked what he’d discussed with Marco Rubio and Steve Witkoff, he said it again: on Iran, it’s “simply a question of when do I want to end it.”',
