      'At 3:31pm ET on Monday he posted on Truth Social: “Anybody reporting Voter Fraud in the past Elections, or the upcoming 2026 Midterm Election, will be paid $1,000,000 upon the arrest and conviction of those that created the Fraud!” The same afternoon at Joint Base Andrews, he was asked whether automatically deporting any non-citizen who votes would clean up elections. “Well, I think so,” he said. “I’m also going to be issuing a million-dollar bonus or reward or whatever you want to call it for anybody that reports voter fraud leading to the arrest and conviction of somebody. We’re giving that person a million dollars.”',
      '“Bonus or reward or whatever you want to call it” is the most detail he has given. ABC News reports it is not clear where the money would come from, and that he has repeatedly made unfounded claims of fraud in past elections. He didn’t say who pays, who decides, or what counts. “Past Elections” is doing some heavy lifting too, because the past election he’s most upset about is the one he lost.',
      'Eight days before the 2026 midterms, the President of the United States is offering a seven-figure prize for proof of the thing he keeps saying happened. His own attorney general said in December 2020 that the Justice Department found no fraud on a scale that could have changed the 2020 result. Now there’s a check on offer, terms to follow.',
