      'Good news, drivers: the president always expected your gas to cost a lot more. In Port Huron, Michigan on Sunday, he said that when he made the Iran decision, “I thought gas would be double and triple. And it’s a small price to pay for taking a nuclear weapon away from maniacs.”',
      'The lead-in was the pep talk: “Short term, you’re taking a hit.” Then, reassuringly: “It’s not a big hit. I thought gasoline would go up much more.” The hit, per AAA on Sunday: regular at a $4.29 national average, against $3.06 a year ago. Diesel at $6.35, against $3.66. By our math, that’s up about 40% and 74%. Not double. Just your problem.',
