      'The president has worked out who’s responsible if the midterms go badly, and good news: it isn’t the president. In Port Huron, Michigan on Sunday, he listed what Democrats would bring back, “all this junk, open borders,” men in women’s sports, “transgender for everybody,” and said it would all “be put right back in as soon as they win.” Then the verdict, pre-filed: “you will only have yourselves to blame.”',
