    body: [
      'On Saturday, the day Barack Obama rallied Democrats in Detroit, Trump told his crowd in Perry, Georgia, how it went: “You know, I saw Barack Hussein Obama was in Michigan and the place was empty.” He even did the other side’s lines for them: “And they were saying, oh, this is a large crowd coming, the people are trickling through.”',
      'Bridge Michigan, reporting from Detroit, describes Obama “appealing to a crowd of more than 4,300 Michigan voters on the first day of early in-person voting.” That’s a lot of empty.',
      'Then it was on to the real subject. “They don’t talk about my crowds, they never talk about them. My biggest was 117,000.” He added Butler, Pennsylvania at “115” and finished with “the biggest crowds ever by anybody, ever.” Those are his numbers.',
      'At 12:42am ET he took it to Truth Social. “Obama was a grossly incompetent President!” and now “he’s campaigning for a Muslim Brotherhood Jihadist,” which is his claim about Abdul El-Sayed, who has denied any affiliation with the group. Bridge Michigan says it found no evidence he “pledged his support” to it. Trump also called El-Sayed “a Fake Doctor.” Bridge Michigan’s fact check says El-Sayed holds a doctor of medicine degree from Columbia but isn’t a licensed physician and doesn’t treat patients. Trump’s next stop is Port Huron, Michigan, on Sunday. We’ll bring a tape measure.',
    ],
