    title: 'Trump tells Georgia to make data centers pay ‘$20,000 for everybody that lives in the community’',
    category: 'REPORTS',
    date: '2026-10-24',
    dek: 'Trump on data centers: “Tell them to pay you $10,000, $15,000, $20,000 for everybody that lives in the community. They’ll do it.”',
    publishedAt: '2026-10-25T14:38:00+02:00',
    topics: ['gaffes'],
