      'At Saturday’s gaggle after he voted, a questioner who said their dad is a Chicago police sergeant asked whether he could send the National Guard into Illinois without JB Pritzker’s approval. “I mean, you can violate the governor. You can go in.” The governor is “supposed to ask for help,” he allowed, but there are “national emergencies like in Chicago, where we could have that place fixed up in two weeks.” And: “I could set that up.”',
