      'Trump has two opinions of the Wall Street Journal, and on Saturday he got through both in under a minute.',
      'At the gaggle after he voted early in Palm Beach, a Journal reporter asked how far along he was on a possible attack on Iran. “Would you really think I’d tell you that?” he said, then: “can anybody from the Wall Street Journal ask a question so stupid?” Then he answered it anyway: “well, we’re thinking about doing it and maybe tomorrow.” Whether that was a joke, a threat or a scheduling update, he didn’t say. He added that there’s also “a possibility” of “a nice big beautiful agreement.” Earlier in the same gaggle he’d told the paper it “has lost its way.”',
