      'Here’s Wednesday night’s route at Clemson, in about six minutes: the Nobel Peace Prize, which he called the Pulitzer. Stephen Hubbard’s release from Russia. The Pulitzer, which he says he deserves “for writing.” The Nobel again. Time magazine’s Person of the Year, which he says this time went to “a machine or something because they couldn’t give it to a human being.” Time’s owner, who he says told him, “we never do it two years in a row.” English as the official language. Then a check-in: “I hope you’re having a good time today, because I’m in a good mood.”',
      'Then the defense: “Because the fake news would say, ‘He rambled.’ I don’t, I don’t ramble. I got, I know everything I’m doing. I got aptitude that they dream about.”',
      'For the record, Time’s 2025 pick was “The Architects of AI,” a group of people that included Elon Musk, Jensen Huang and Sam Altman. Human beings, all of them, as far as anyone knows. A few seconds after the aptitude line, he told the crowd, “I’m in a good mood today.” Again. That isn’t a ramble. It’s a loop.',
