      'Donald Trump has a favorite number, and on Wednesday night it got away from him.',
      'At Clemson he started where he always does: “we secured commitments for $22.2 trillion in new investments coming into the United States,” the “largest amount of money ever invested in our country, times five.” Then it slipped: “We’ve never had so much money at $22.2 million.” The correction came fast: “Billion, sorry, billion. With a B, not an M. If it was an M, we’d be in big trouble. With a B, $22 billion.” Then on to tariffs, his “fifth favorite” word.',
