      'He was deep in his usual riff about Roy Cooper’s 2021 prison settlement, the one he calls “far worse than Willie Horton,” when he landed the line: “he released them into our society and he’s going to become your Senator and it’s crazy.” He meant it as a warning. It came out as a forecast.',
